    }
    if (@typeInfo(dst.Input).@"struct".decl_names.len != 0)
        @compileError("Input must not expose public methods");
    if (@typeInfo(dst.Output).@"struct".decl_names.len != 0)
        @compileError("Output must not expose public methods");
