                        else => {},
                    }
                }
            },
            else => {},
        }
    }
    for (.{
        "apply",          "execute",           "grant",
        "revoke",         "mint",              "transmit",
        "session",        "callback",          "Visitor",
        "ProjectionData", "DurableOperLookup", "Services",
        "Store",          "reconcile",         "executeAuthorized",
    }) |name| {
        if (@hasDecl(dst, name))
            @compileError("OCG2 transaction DST must not expose a runtime privilege surface");
    }
}

